fn days_to_next_sunday(day: &str) -> i8 {
    // Map each day abbreviation to an index (Sunday = 0)
    let day_index = match day {
        "SUN" => 0,
        "MON" => 1,
        "TUE" => 2,
        "WED" => 3,
        "THU" => 4,
        "FRI" => 5,
        "SAT" => 6,
        // Since problem states input is always valid, no need for fallback,
        // but it is good practice to handle unexpected inputs:
        _ => panic!("Invalid day abbreviation"),
    };

    // If it's Sunday, next Sunday is 7 days away.
    // Otherwise, it's 7 - day_index.
    if day_index == 0 {
        7
    } else {
        7 - day_index
    }
}